create temporary table pasta1_import_gate on commit drop as
select
  (select count(*) from public.slt_projects_works where deleted_at is null)=858
  and (select count(*) from public.slt_budget_estimates where deleted_at is null)=855
  and (select count(*) from public.slt_budget_demands where deleted_at is null)=20 as enabled;

do $$
declare snapshot jsonb; snapshot_count integer; snapshot_bytes bigint;
  active_works integer; active_evs integer; active_demands integer;
begin
  if not (select enabled from pasta1_import_gate) then
    return;
  end if;
  if (select count(*) from pasta1_work_plan)<>862 then
    raise exception 'Importação cancelada: esperado 862 linhas, encontrado %',(select count(*) from pasta1_work_plan);
  end if;
  if exists(select 1 from pasta1_work_plan group by source_row having count(*)>1) then
    raise exception 'Importação cancelada: linha da planilha repetida';
  end if;
  if exists(select 1 from pasta1_work_plan group by target_key having count(*)>1) then
    raise exception 'Importação cancelada: duas linhas apontam para a mesma obra';
  end if;
  if (select count(*) from pasta1_work_plan where is_new)<>413
     or (select count(*) from pasta1_work_plan where not is_new)<>449 then
    raise exception 'Importação cancelada: plano de associação divergente';
  end if;
  select count(*) into active_works from public.slt_projects_works where deleted_at is null;
  select count(*) into active_evs from public.slt_budget_estimates where deleted_at is null;
  select count(*) into active_demands from public.slt_budget_demands where deleted_at is null;
  if exists(select 1 from pasta1_work_plan p left join public.slt_projects_works w on w.record_key=p.target_key and w.deleted_at is null where not p.is_new and w.record_key is null) then
    raise exception 'Importação cancelada: associação aponta para obra inexistente';
  end if;
  if exists(select 1 from pasta1_work_plan p join public.slt_projects_works w on w.record_key=p.target_key and w.deleted_at is null where p.is_new) then
    raise exception 'Importação cancelada: identificador de nova obra já existe';
  end if;
  snapshot=slt_private.capture_app_snapshot();
  snapshot_count=jsonb_array_length(coalesce(snapshot->'records','[]'::jsonb));
  snapshot_bytes=octet_length(snapshot::text);
  insert into slt_private.state_backups(created_by,kind,label,schema_version,record_count,size_bytes,snapshot)
  values(null,'manual','Antes de associar Pasta1.xlsx às obras',2,snapshot_count,snapshot_bytes,snapshot);
end $$;

update public.slt_projects_works w
set revision=w.revision+1,updated_at=now(),state_code=p.uf,region=case p.uf
    when 'AC' then 'Norte' when 'AP' then 'Norte' when 'AM' then 'Norte' when 'PA' then 'Norte' when 'RO' then 'Norte' when 'RR' then 'Norte' when 'TO' then 'Norte'
    when 'AL' then 'Nordeste' when 'BA' then 'Nordeste' when 'CE' then 'Nordeste' when 'MA' then 'Nordeste' when 'PB' then 'Nordeste' when 'PE' then 'Nordeste' when 'PI' then 'Nordeste' when 'RN' then 'Nordeste' when 'SE' then 'Nordeste'
    when 'DF' then 'Centro-Oeste' when 'GO' then 'Centro-Oeste' when 'MT' then 'Centro-Oeste' when 'MS' then 'Centro-Oeste'
    when 'ES' then 'Sudeste' when 'MG' then 'Sudeste' when 'RJ' then 'Sudeste' when 'SP' then 'Sudeste'
    when 'PR' then 'Sul' when 'RS' then 'Sul' when 'SC' then 'Sul'
    else '' end,
  extra=coalesce(w.extra,'{}'::jsonb)||jsonb_build_object(
    'tipoUnidade',p.tipo_unidade,
    'prazoDias',coalesce(to_jsonb(p.prazo_dias),'""'::jsonb),
    'anoObra',p.ano_obra,
    'classificacaoObra',p.classificacao_obra,
    'tipologiaObra',p.tipologia_obra,
    '_pasta1Import',true,
    '_pasta1SourceRow',p.source_row,
    '_pasta1Scope',p.scope,
    '_pasta1Criterion',p.criterion)
from pasta1_work_plan p
where not p.is_new and w.record_key=p.target_key and w.deleted_at is null
  and (select enabled from pasta1_import_gate);

insert into public.slt_projects_works(
  record_key,revision,ordinal,parent_key,child_fields,field_keys,empty_fields,string_fields,extra,
  created_at,updated_at,updated_by,deleted_at,id,state_code,area_m2,tax_id,name,unit_name,city,region,
  status,planned_end,planned_start,planned_amount,realized_amount,code,contracted_amount,internal_order)
select p.target_key,1,b.base_ordinal+row_number() over(order by p.source_row),null,array['ev'],
  array['id','nome','codigoOriginal','status','uf','regiao','area','tipoUnidade','prazoDias','anoObra','classificacaoObra','tipologiaObra'],
  array[]::text[],array[]::text[],
  jsonb_build_object(
    'chaveUnica',p.target_key,'tipoUnidade',p.tipo_unidade,'unidadeTipo',p.tipo_unidade,
    'unidadeNome',p.name,'unidadeMunicipio',p.uf,
    'prazoDias',coalesce(to_jsonb(p.prazo_dias),'""'::jsonb),'anoObra',p.ano_obra,
    'classificacaoObra',p.classificacao_obra,'tipologiaObra',p.tipologia_obra,
    'areaConstruida',0,'areaEquivalente',0,'source','Pasta1.xlsx',
    '_pasta1Import',true,'_pasta1SourceRow',p.source_row,'_pasta1Scope',p.scope,'_pasta1Criterion',p.criterion),
  now(),now(),null,null,p.target_key,p.uf,0,'',p.name,p.name,'',case p.uf
    when 'AC' then 'Norte' when 'AP' then 'Norte' when 'AM' then 'Norte' when 'PA' then 'Norte' when 'RO' then 'Norte' when 'RR' then 'Norte' when 'TO' then 'Norte'
    when 'AL' then 'Nordeste' when 'BA' then 'Nordeste' when 'CE' then 'Nordeste' when 'MA' then 'Nordeste' when 'PB' then 'Nordeste' when 'PE' then 'Nordeste' when 'PI' then 'Nordeste' when 'RN' then 'Nordeste' when 'SE' then 'Nordeste'
    when 'DF' then 'Centro-Oeste' when 'GO' then 'Centro-Oeste' when 'MT' then 'Centro-Oeste' when 'MS' then 'Centro-Oeste'
    when 'ES' then 'Sudeste' when 'MG' then 'Sudeste' when 'RJ' then 'Sudeste' when 'SP' then 'Sudeste'
    when 'PR' then 'Sul' when 'RS' then 'Sul' when 'SC' then 'Sul'
    else '' end,
  'Importada',null,null,0,0,p.code,0,''
from pasta1_work_plan p
cross join lateral(select coalesce(max(ordinal),0) base_ordinal from public.slt_projects_works where deleted_at is null)b
where p.is_new and (select enabled from pasta1_import_gate);

do $$
declare active_works integer; active_evs integer; active_demands integer; imported_rows integer;
begin
  if not (select enabled from pasta1_import_gate) then
    return;
  end if;
  select count(*) into active_works from public.slt_projects_works where deleted_at is null;
  select count(*) into active_evs from public.slt_budget_estimates where deleted_at is null;
  select count(*) into active_demands from public.slt_budget_demands where deleted_at is null;
  select count(*) into imported_rows from public.slt_projects_works where deleted_at is null and extra->>'_pasta1Import'='true';
  if active_works<>1271 or active_evs<>855 or active_demands<>20 or imported_rows<>862 then
    raise exception 'Importação inconsistente: obras %, EVs %, demandas %, linhas associadas %',active_works,active_evs,active_demands,imported_rows;
  end if;
  if (select count(distinct extra->>'_pasta1SourceRow') from public.slt_projects_works where deleted_at is null and extra->>'_pasta1Import'='true')<>862 then
    raise exception 'Importação inconsistente: linhas da planilha duplicadas';
  end if;
  if exists(select 1 from public.slt_budget_demands d left join public.slt_projects_works w on w.record_key=d.work_id and w.deleted_at is null where d.deleted_at is null and w.record_key is null) then
    raise exception 'Importação inconsistente: demanda ativa sem obra ativa';
  end if;
end $$;

commit;
